customScripts.auto_carousel_slider:
(function vehicleCarousel(root, ctx) {
  if (!root) return;
  const track = root.querySelector('.auto-carousel-track');
  const viewport = root.querySelector('.auto-carousel-viewport');
  const slides = [...root.querySelectorAll('.auto-slide')];
  if (!track || !viewport || !slides.length || root.dataset.mfCarouselReady) return;
  root.dataset.mfCarouselReady = '1';
  const previous = root.querySelector('.auto-carousel-prev');
  const next = root.querySelector('.auto-carousel-next');
  const dots = [...root.querySelectorAll('.auto-dot')];
  const removers = [];
  let index = 0, timer;
  const metrics = () => {
    const gap = parseFloat(getComputedStyle(track).gap) || 0;
    const step = slides[0].getBoundingClientRect().width + gap;
    const visible = Math.max(1, Math.round((viewport.clientWidth + gap) / step));
    return { step, max: Math.max(0, slides.length - visible) };
  };
  const render = () => {
    const { step, max } = metrics();
    index = Math.min(max, Math.max(0, index));
    track.style.transform = `translateX(-${index * step}px)`;
    if (previous) previous.disabled = index === 0;
    if (next) next.disabled = index === max;
    dots.forEach((dot, i) => {
      dot.hidden = i > max;
      dot.classList.toggle('active', i === index);
      dot.setAttribute('aria-current', i === index ? 'true' : 'false');
      dot.setAttribute('aria-label', `Vehicle group ${i + 1}`);
    });
  };
  const restart = () => {
    clearInterval(timer);
    if (!matchMedia('(prefers-reduced-motion: reduce)').matches) {
      timer = setInterval(() => { index = index >= metrics().max ? 0 : index + 1; render(); }, 5000);
    }
  };
  const go = value => { index = value; render(); restart(); };
  const listen = (element, event, handler, options) => {
    if (!element) return;
    element.addEventListener(event, handler, options);
    removers.push(() => element.removeEventListener(event, handler, options));
  };
  listen(previous, 'click', () => go(index - 1));
  listen(next, 'click', () => go(index + 1));
  dots.forEach((dot, i) => listen(dot, 'click', () => go(i)));
  listen(root, 'mouseenter', () => clearInterval(timer));
  listen(root, 'mouseleave', restart);
  listen(root, 'focusin', () => clearInterval(timer));
  listen(root, 'focusout', restart);
  let touchX;
  listen(viewport, 'touchstart', e => { touchX = e.touches[0].clientX; }, { passive: true });
  listen(viewport, 'touchend', e => {
    const delta = touchX - e.changedTouches[0].clientX;
    if (Math.abs(delta) > 50) go(index + (delta > 0 ? 1 : -1));
    touchX = undefined;
  }, { passive: true });
  const observer = new ResizeObserver(render);
  observer.observe(viewport);
  ctx.registerCleanup(() => {
    clearInterval(timer); observer.disconnect(); removers.forEach(remove => remove());
    delete root.dataset.mfCarouselReady;
  });
  render(); restart();
})(__mfScriptContext.container.querySelector('.auto-dealership'), __mfScriptContext);

